-- =====================================================================
-- GenBit Dataset (EN) — sample relational database
-- Universe: GenBit, a scientific conglomerate in the year 2188 (genetics,
-- quantum physics, neuroscience, terraforming...).
-- All data is fictional. Currency: galactic credits (GC).
-- License: CC BY 4.0 — https://github.com/manuherran/genbit-dataset
-- Auto-generated by generator/build.py — do not edit by hand.
-- =====================================================================

DROP DATABASE IF EXISTS db_genbit_en;
CREATE DATABASE db_genbit_en CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE db_genbit_en;

-- Step 1: tables, primary and foreign keys

-- Planets, moons and stations where GenBit operates.
CREATE TABLE t_planet (
  id INT NOT NULL,
  name VARCHAR(50) NOT NULL,
  star_system VARCHAR(50) NOT NULL,
  body_type VARCHAR(50) NOT NULL,
  distance_ly DECIMAL(8,2) NOT NULL,
  gravity_g DECIMAL(4,2) NOT NULL,
  population BIGINT NOT NULL,
  habitable BOOLEAN NOT NULL,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- GenBit group companies and partners. parent_company_id points to the parent company.
CREATE TABLE t_company (
  id INT NOT NULL,
  acronym VARCHAR(10) NOT NULL,
  name VARCHAR(80) NOT NULL,
  sector VARCHAR(50) NOT NULL,
  hq_planet_id INT NOT NULL,
  founded_year INT NOT NULL,
  parent_company_id INT NULL,
  headcount INT NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT fk_company_1 FOREIGN KEY (hq_planet_id) REFERENCES t_planet (id),
  CONSTRAINT fk_company_2 FOREIGN KEY (parent_company_id) REFERENCES t_company (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Offices and labs of each company.
CREATE TABLE t_office (
  id INT NOT NULL,
  name VARCHAR(80) NOT NULL,
  company_id INT NOT NULL,
  planet_id INT NOT NULL,
  city VARCHAR(50) NOT NULL,
  capacity INT NOT NULL,
  opening_date DATE NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT fk_office_1 FOREIGN KEY (company_id) REFERENCES t_company (id),
  CONSTRAINT fk_office_2 FOREIGN KEY (planet_id) REFERENCES t_planet (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- GenBit employees. manager_id is a self-reference (employee → manager).
CREATE TABLE t_employee (
  id INT NOT NULL,
  first_name VARCHAR(50) NOT NULL,
  last_name VARCHAR(80) NULL,
  email VARCHAR(100) NOT NULL,
  job_title VARCHAR(80) NOT NULL,
  department VARCHAR(50) NOT NULL,
  office_id INT NULL,
  manager_id INT NULL,
  hire_date DATE NOT NULL,
  salary DECIMAL(10,2) NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT fk_employee_1 FOREIGN KEY (office_id) REFERENCES t_office (id),
  CONSTRAINT fk_employee_2 FOREIGN KEY (manager_id) REFERENCES t_employee (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Company phones. An employee may have several; some are unassigned.
CREATE TABLE t_mobile (
  number VARCHAR(15) NOT NULL,
  puk VARCHAR(10) NOT NULL,
  model VARCHAR(50) NOT NULL,
  carrier VARCHAR(50) NOT NULL,
  employee_id INT NULL,
  PRIMARY KEY (number),
  CONSTRAINT fk_mobile_1 FOREIGN KEY (employee_id) REFERENCES t_employee (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Customers from all over the galaxy (human and non-human).
CREATE TABLE t_customer (
  id INT NOT NULL,
  first_name VARCHAR(50) NOT NULL,
  last_name VARCHAR(80) NULL,
  species VARCHAR(50) NOT NULL,
  email VARCHAR(100) NULL,
  planet_id INT NOT NULL,
  company_id INT NULL,
  signup_date DATE NOT NULL,
  tier VARCHAR(20) NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT fk_customer_1 FOREIGN KEY (planet_id) REFERENCES t_planet (id),
  CONSTRAINT fk_customer_2 FOREIGN KEY (company_id) REFERENCES t_company (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Parts suppliers.
CREATE TABLE t_supplier (
  id INT NOT NULL,
  first_name VARCHAR(50) NOT NULL,
  last_name VARCHAR(80) NOT NULL,
  business_name VARCHAR(80) NOT NULL,
  specialty VARCHAR(50) NOT NULL,
  planet_id INT NOT NULL,
  rating DECIMAL(2,1) NOT NULL,
  email VARCHAR(100) NULL,
  PRIMARY KEY (id),
  CONSTRAINT fk_supplier_1 FOREIGN KEY (planet_id) REFERENCES t_planet (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Investors. Some are also employees (employee_id).
CREATE TABLE t_investor (
  id INT NOT NULL,
  first_name VARCHAR(50) NOT NULL,
  last_name VARCHAR(80) NOT NULL,
  employee_id INT NULL,
  company_id INT NOT NULL,
  shares INT NOT NULL,
  investment_date DATE NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT fk_investor_1 FOREIGN KEY (employee_id) REFERENCES t_employee (id),
  CONSTRAINT fk_investor_2 FOREIGN KEY (company_id) REFERENCES t_company (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Research projects (genetics, quantum physics, neuroscience…).
CREATE TABLE t_project (
  id INT NOT NULL,
  name VARCHAR(80) NOT NULL,
  area VARCHAR(50) NOT NULL,
  company_id INT NOT NULL,
  lead_employee_id INT NULL,
  start_date DATE NOT NULL,
  end_date DATE NULL,
  budget DECIMAL(14,2) NOT NULL,
  status VARCHAR(20) NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT fk_project_1 FOREIGN KEY (company_id) REFERENCES t_company (id),
  CONSTRAINT fk_project_2 FOREIGN KEY (lead_employee_id) REFERENCES t_employee (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- N-M relationship between employees and projects.
CREATE TABLE t_assignment (
  employee_id INT NOT NULL,
  project_id INT NOT NULL,
  role VARCHAR(30) NOT NULL,
  weekly_hours INT NOT NULL,
  PRIMARY KEY (employee_id, project_id),
  CONSTRAINT fk_assignment_1 FOREIGN KEY (employee_id) REFERENCES t_employee (id),
  CONSTRAINT fk_assignment_2 FOREIGN KEY (project_id) REFERENCES t_project (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Patients in GenBit clinical trials.
CREATE TABLE t_patient (
  id INT NOT NULL,
  first_name VARCHAR(50) NOT NULL,
  last_name VARCHAR(80) NULL,
  birth_date DATE NOT NULL,
  species VARCHAR(50) NOT NULL,
  blood_type VARCHAR(3) NULL,
  planet_id INT NOT NULL,
  project_id INT NULL,
  admission_date DATE NOT NULL,
  status VARCHAR(30) NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT fk_patient_1 FOREIGN KEY (planet_id) REFERENCES t_planet (id),
  CONSTRAINT fk_patient_2 FOREIGN KEY (project_id) REFERENCES t_project (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Newsletter subscribers. No foreign keys: match them by email.
CREATE TABLE t_subscriber (
  email VARCHAR(100) NOT NULL,
  signup_date DATE NOT NULL,
  language VARCHAR(2) NOT NULL,
  newsletter VARCHAR(50) NOT NULL,
  active BOOLEAN NOT NULL,
  PRIMARY KEY (email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Product lines.
CREATE TABLE t_product_line (
  id INT NOT NULL,
  name VARCHAR(80) NOT NULL,
  description VARCHAR(200) NOT NULL,
  PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Products for sale. Prices in galactic credits (GC).
CREATE TABLE t_product (
  id INT NOT NULL,
  name VARCHAR(80) NOT NULL,
  product_line_id INT NOT NULL,
  project_id INT NULL,
  price DECIMAL(12,2) NOT NULL,
  stock INT NOT NULL,
  launch_date DATE NOT NULL,
  weight_kg DECIMAL(10,2) NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT fk_product_1 FOREIGN KEY (product_line_id) REFERENCES t_product_line (id),
  CONSTRAINT fk_product_2 FOREIGN KEY (project_id) REFERENCES t_project (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Parts and components.
CREATE TABLE t_piece (
  id INT NOT NULL,
  name VARCHAR(80) NOT NULL,
  material VARCHAR(50) NOT NULL,
  supplier_id INT NULL,
  cost DECIMAL(10,2) NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT fk_piece_1 FOREIGN KEY (supplier_id) REFERENCES t_supplier (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Bill of materials: which parts each product uses (N-M).
CREATE TABLE t_product_piece (
  product_id INT NOT NULL,
  piece_id INT NOT NULL,
  quantity INT NOT NULL,
  PRIMARY KEY (product_id, piece_id),
  CONSTRAINT fk_product_piece_1 FOREIGN KEY (product_id) REFERENCES t_product (id),
  CONSTRAINT fk_product_piece_2 FOREIGN KEY (piece_id) REFERENCES t_piece (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Customer orders, handled by a sales employee.
CREATE TABLE t_order (
  id INT NOT NULL,
  customer_id INT NOT NULL,
  employee_id INT NULL,
  order_date DATE NOT NULL,
  delivery_date DATE NULL,
  destination_planet_id INT NOT NULL,
  status VARCHAR(30) NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT fk_order_1 FOREIGN KEY (customer_id) REFERENCES t_customer (id),
  CONSTRAINT fk_order_2 FOREIGN KEY (employee_id) REFERENCES t_employee (id),
  CONSTRAINT fk_order_3 FOREIGN KEY (destination_planet_id) REFERENCES t_planet (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Lines of each order.
CREATE TABLE t_order_line (
  order_id INT NOT NULL,
  line_number INT NOT NULL,
  product_id INT NOT NULL,
  quantity INT NOT NULL,
  unit_price DECIMAL(12,2) NOT NULL,
  discount_pct DECIMAL(5,2) NOT NULL,
  PRIMARY KEY (order_id, line_number),
  CONSTRAINT fk_order_line_1 FOREIGN KEY (order_id) REFERENCES t_order (id),
  CONSTRAINT fk_order_line_2 FOREIGN KEY (product_id) REFERENCES t_product (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Order payments (several per order allowed; negative amounts = refunds).
CREATE TABLE t_payment (
  id INT NOT NULL,
  order_id INT NOT NULL,
  payment_date DATE NOT NULL,
  amount DECIMAL(14,2) NOT NULL,
  method VARCHAR(50) NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT fk_payment_1 FOREIGN KEY (order_id) REFERENCES t_order (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

